import React from "react";
import { spring, interpolate, useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlusJakartaSans = makeLoadFont('PlusJakartaSans');

// Load Google Font at module level
const { fontFamily } = loadPlusJakartaSans();

// Schema definition matching strict rules


export type GraphArrowAnimationProps = Record<string, any>;

// DotGrid Component for background decorations
const DotGrid: React.FC<{
  rows: number;
  cols: number;
  dotSize: number;
  spacing: number;
  color: string;
  opacity: number;
}> = ({ rows, cols, dotSize, spacing, color, opacity }) => {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: spacing, opacity, transition: "none" }}>
      {Array.from({ length: rows }).map((_, r) => (
        <div key={r} style={{ display: "flex", flexDirection: "row", gap: spacing, transition: "none" }}>
          {Array.from({ length: cols }).map((_, c) => (
            <div
              key={c}
              style={{
                width: dotSize,
                height: dotSize,
                borderRadius: "50%",
                backgroundColor: color,
                transition: "none",
              }}
            />
          ))}
        </div>
      ))}
    </div>
  );
};

const GraphArrowAnimation: React.FC<GraphArrowAnimationProps> = ({
  backgroundColor = "#07111e",
  axisColor = "#ffffff",
  lineColor = "#ff4d4d",
  dotColor = "#1e2d42",
  gridOpacity = 0.4,
  studioName = "Malloy Studio",
  durationInSeconds = 8,
  transparentBackground = false,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safe background calculation
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Layout Ratios matching target visual composition
  const startX = width * 0.175;
  const endX = width * 0.80;

  const startY = height * 0.85;
  const plateauY = height * 0.35; // The horizontal plateau height

  // Small scale factor for responsive dot sizes and stroke widths
  const sizeScale = Math.min(width, height);
  const dotSize = sizeScale * 0.005;
  const dotSpacing = sizeScale * 0.016;
  const axisWidth = sizeScale * 0.004;
  const lineWidth = sizeScale * 0.006;
  const arrowScale = sizeScale / 1080;

  // 1. Intro Animation: Background Glows & Dot Grids Fade In
  const bgElementsOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Axes Spring In
  const axisSpring = spring({
    frame,
    fps,
    config: { damping: 15, stiffness: 90 },
  });

  const currentXAxisX = interpolate(axisSpring, [0, 1], [startX, endX]);
  const currentYAxisY = interpolate(axisSpring, [0, 1], [startY, plateauY - height * 0.05]);

  // 3. Studio Name Text Fade and Slide Up
  const textOpacity = interpolate(frame, [12, 32], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const textTranslateY = interpolate(frame, [12, 32], [15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 4. Graph Line & Arrow Animation (starts after axes are drawn)
  const lineSpring = spring({
    frame: frame - 25,
    fps,
    config: { damping: 18, stiffness: 45, mass: 1.1 },
  });

  // Gentle hover loop that kicks in after the line finishes drawing
  const hoverActive = interpolate(frame, [75, 95], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const hoverY = Math.sin(frame * 0.05) * (sizeScale * 0.01) * hoverActive;

  // Current Y of the plateau, incorporating the hover effect
  const currentPlateauY = plateauY + hoverY;

  // Interpolated Coordinates of the leading Arrow using the plateau Bezier curve
  const t = lineSpring;
  const arrowX = startX + t * (endX - startX);
  const arrowY = Math.pow(1 - t, 3) * startY + (1 - Math.pow(1 - t, 3)) * currentPlateauY;

  // Generate smooth polyline points for the curve up to the current animated point
  const points = [];
  const steps = 100;
  for (let i = 0; i <= steps; i++) {
    const stepT = (i / steps) * t;
    const px = startX + stepT * (endX - startX);
    const py = Math.pow(1 - stepT, 3) * startY + (1 - Math.pow(1 - stepT, 3)) * currentPlateauY;
    points.push(`${px},${py}`);
  }
  const pointsString = points.join(" ");

  // Calculate Arrow Slope Angle using the instantaneous derivative of the Bezier path
  const dx_dt = endX - startX;
  const dy_dt = -3 * Math.pow(1 - t, 2) * (startY - currentPlateauY);
  const angleRad = Math.atan2(dy_dt, dx_dt);
  const angleDeg = (angleRad * 180) / Math.PI;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, overflow: "hidden" }}>
      {/* Background Decorative Circular Glows */}
      <div
        style={{
          position: "absolute",
          top: -height * 0.25,
          right: -width * 0.15,
          width: width * 0.5,
          height: width * 0.5,
          borderRadius: "50%",
          background: "radial-gradient(circle, rgba(255, 77, 77, 0.15) 0%, rgba(7, 17, 30, 0) 70%)",
          opacity: bgElementsOpacity,
          pointerEvents: "none",
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          bottom: -height * 0.25,
          left: -width * 0.15,
          width: width * 0.5,
          height: width * 0.5,
          borderRadius: "50%",
          background: "radial-gradient(circle, rgba(30, 48, 80, 0.4) 0%, rgba(7, 17, 30, 0) 70%)",
          opacity: bgElementsOpacity,
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Decorative Dot Grids */}
      <div
        style={{
          position: "absolute",
          top: height * 0.12,
          left: width * 0.06,
          transition: "none",
        }}
      >
        <DotGrid
          rows={6}
          cols={4}
          dotSize={dotSize}
          spacing={dotSpacing}
          color={dotColor}
          opacity={bgElementsOpacity * gridOpacity}
        />
      </div>

      <div
        style={{
          position: "absolute",
          bottom: height * 0.12,
          right: width * 0.06,
          transition: "none",
        }}
      >
        <DotGrid
          rows={6}
          cols={4}
          dotSize={dotSize}
          spacing={dotSpacing}
          color={dotColor}
          opacity={bgElementsOpacity * gridOpacity}
        />
      </div>

      {/* Main Axes */}
      <svg
        style={{
          position: "absolute",
          width,
          height,
          overflow: "visible",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {/* Y Axis */}
        <line
          x1={startX}
          y1={startY}
          x2={startX}
          y2={currentYAxisY}
          stroke={axisColor}
          strokeWidth={axisWidth}
          strokeLinecap="round"
          style={{ transition: "none" }}
        />
        {/* X Axis */}
        <line
          x1={startX}
          y1={startY}
          x2={currentXAxisX}
          y2={startY}
          stroke={axisColor}
          strokeWidth={axisWidth}
          strokeLinecap="round"
          style={{ transition: "none" }}
        />
      </svg>

      {/* Animated Graph Line and Arrowhead */}
      <svg
        style={{
          position: "absolute",
          width,
          height,
          overflow: "visible",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {/* Graph Line Shadow / Glow */}
        <polyline
          points={pointsString}
          fill="none"
          stroke={lineColor}
          strokeWidth={lineWidth * 3.5}
          strokeLinecap="round"
          strokeLinejoin="round"
          opacity={0.18}
          style={{ transition: "none" }}
        />
        {/* Main Graph Line */}
        <polyline
          points={pointsString}
          fill="none"
          stroke={lineColor}
          strokeWidth={lineWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ transition: "none" }}
        />
        {/* Arrowhead */}
        <path
          d="M -24 -11 L 3 0 L -24 11 C -21 5, -21 -5, -24 -11 Z"
          fill={lineColor}
          transform={`translate(${arrowX}, ${arrowY}) scale(${arrowScale}) rotate(${angleDeg})`}
          style={{ transition: "none" }}
        />
      </svg>

      {/* Branding / Studio Text */}
      <div
        style={{
          position: "absolute",
          left: width * 0.06,
          bottom: height * 0.06,
          fontFamily,
          fontSize: sizeScale * 0.045,
          fontWeight: 700,
          color: "#ffffff",
          opacity: textOpacity,
          transform: `translateY(${textTranslateY}px)`,
          transition: "none",
        }}
      >
        {studioName}
      </div>
    </AbsoluteFill>
  );
};

export default GraphArrowAnimation;